from pathlib import Path
import re
root=Path.cwd(); p=Path('tmp/pdf-review/crm-case-study.html'); s=p.read_text()
css='''@page showcase{size:A4 landscape;margin:0}.visual{background:#f8fafc}.visual h3{font-size:14pt;margin:7mm 0 3mm}.palette{display:grid;grid-template-columns:repeat(3,1fr);gap:4mm}.swatch{background:white;border:1px solid #e2e8f0;border-radius:3mm;overflow:hidden}.chip{height:17mm}.swatch p{padding:2mm 3mm;font-size:8pt;margin:0}.two{display:grid;grid-template-columns:1fr 1fr;gap:5mm}.sample{background:white;border:1px solid #e2e8f0;padding:5mm;border-radius:4mm;margin:4mm 0}.type-lg{font-size:28px;font-weight:700;line-height:1.2}.type-md{font-size:18px;font-weight:600}.muted{color:#64748b}.button{display:inline-block;border-radius:99px;padding:10px 16px;font-size:12px;font-weight:600;margin:2mm 1mm 2mm 0;background:#4d76bb;color:white}.secondary{background:white;border:1px solid #e2e8f0;color:#0f172a}.danger{background:#e53e2b}.disabled{opacity:.5}.field{border:1px solid #e2e8f0;border-radius:12px;padding:10px 14px;margin:2mm 0;background:white;font-size:14px}.focus{border-color:#4d76bb;box-shadow:0 0 0 4px #eef3fa}.badge{display:inline-block;padding:2mm 3mm;border-radius:99px;background:#eef3fa;color:#3e6199;margin-right:2mm;font-size:9pt}.dark-sample{background:#090a10;padding:5mm;border-radius:4mm;color:#f1f3f9;margin-top:4mm}.dark-sample .surface{background:#11121c;padding:4mm;border:1px solid #1f2133;border-radius:3mm}.screen-page{page:showcase;padding:11mm 14mm 13mm;min-height:210mm;height:210mm;background:#f8fafc}.screen-page .eyebrow{margin-bottom:2mm;font-size:7pt}.screen-page h2{font-size:20pt;margin-bottom:2mm;max-width:none}.screen-page .screen-desc{font-size:9pt;margin-bottom:4mm;max-width:245mm}.screen-frame{background:white;padding:2mm;border:1px solid #dce4ef;border-radius:3mm;box-shadow:0 3mm 8mm #18304f0d;text-align:center}.screen-frame img{display:block;max-width:100%;height:146mm;object-fit:contain;margin:auto}.screen-page footer{left:14mm;right:14mm;bottom:5mm;font-size:6pt}.note{font-size:8pt;color:#64748b}'''
s=s.replace('</style>',css+'</style>')
def page(title,body,num):return f'<section class="visual"><div class="eyebrow">BHE CRM / VISUAL SYSTEM</div><h2>{title}</h2>{body}<footer>IMPLEMENTATION-BASED STYLE GUIDE <span>{num}</span></footer></section>'
colors=[('Primary','#4d76bb','Actions, selection, data series'),('Accent / warning','#f59e0b','Attention and pending states'),('Success','#45c348','Positive status'),('Danger','#e53e2b','Errors and destructive actions'),('Background','#f8fafc','Workspace canvas'),('Surface','#ffffff','Cards and dialogs'),('Foreground','#0f172a','Primary text'),('Muted text','#64748b','Secondary information'),('Border','#e2e8f0','Separation and field edges')]
a='<p>A restrained blue identity anchors a dense operational workspace. Neutral surfaces separate content; semantic colors identify status and action.</p><div class="palette">'+''.join(f'<div class="swatch"><div class="chip" style="background:{v}"></div><p><strong>{n}</strong><br>{v.upper()}<br>{d}</p></div>' for n,v,d in colors)+'</div><h3>Dark theme</h3><div class="dark-sample"><div class="surface"><strong>Layer surfaces, preserve meaning.</strong><p style="color:#9499b3;margin:2mm 0">Canvas #090A10 · Surface #11121C · Primary #6D93D0<br>Text #F1F3F9 · Border #1F2133</p></div></div><p class="note" style="margin-top:4mm">Tokens are taken from src/app/globals.css. Status must also use text or icons. These swatches do not imply that every foreground/background pairing passes contrast checks.</p>'
b='''<p><strong>Product typeface: Plus Jakarta Sans.</strong> The application configures weights 300–800, with system sans-serif fallbacks. This PDF uses Arial for portable rendering; the CRM screenshots show the product typography.</p><div class="sample"><div class="type-lg">Your next action, clearly visible.</div><p class="muted">Page headings: examples at 24–30px, bold.</p><div class="type-md">Applications needing attention</div><p class="muted">Section headings: examples at 18px, semibold or bold.</p><p style="font-size:14px">Review student details, missing documents, and upcoming deadlines.</p><p class="muted">Body and fields: examples at 14px. Supporting labels: 12px.</p></div><h3>Spacing and layout</h3><table><tr><th>Pattern</th><th>Observed implementation</th></tr><tr><td>Spacing rhythm</td><td>Common gaps and padding use 4, 8, 12, 16, and 24px steps; specialized values also occur.</td></tr><tr><td>Fields</td><td>12px corner radius; 14px horizontal and 10px vertical padding.</td></tr><tr><td>Primary actions</td><td>Pill shape, minimum 40px height; 16px horizontal padding.</td></tr><tr><td>Workspace</td><td>Flexible sidebar and content; main content capped at 1600px, with 16–24px outer padding.</td></tr><tr><td>Containers</td><td>Rounded surfaces, thin borders, restrained shadows; radius varies by component.</td></tr></table><h3>Visual hierarchy</h3><p>Use a clear page title, one prominent task action, supporting filters, and the main work area. Emphasize urgent work through labels and position as well as color.</p><p class="note">Sizes describe implemented examples, not a complete standardized token scale. Consolidating the scale is a recommended next step.</p>'''
c='''<p>Representative specimens below translate shared component classes into a printable guide. Screenshots in the showcase provide the actual product context.</p><h3>Action hierarchy</h3><div class="sample"><span class="button">New application</span><span class="button secondary">Export report</span><span class="button danger">Delete</span><span class="button disabled">Disabled</span><p class="note">Primary: main task. Secondary: supporting action. Danger: destructive action. Hover darkens primary to #3E6199; disabled actions use reduced opacity.</p></div><h3>Fields and focus</h3><div class="two"><div><strong style="font-size:9pt">Student name</strong><div class="field">Enter student name</div><p class="note">Default: neutral border and clear label.</p></div><div><strong style="font-size:9pt">Student name</strong><div class="field focus">Focused field</div><p class="note">Focus: primary border and soft ring.</p></div></div><h3>Status and feedback</h3><div class="sample"><span class="badge">Assigned</span><span class="badge" style="background:#fef3c7;color:#784d00">Pending</span><span class="badge" style="background:#e9f8e9;color:#235b25">Complete</span><p class="note" style="margin-top:3mm">Use explicit labels. These semantic specimens illustrate intended meaning; individual modules have their own stage palettes.</p></div><h3>Interaction guidelines</h3><p>Tables support search, filtering, selection, and contextual actions. Drawers retain list context; modals isolate focused decisions. Show success only after the intended operation has completed.</p><p class="note">Accessibility work remains: verify contrast, complete dialog focus trapping and restoration, check icon labels, and test keyboard and narrow-screen flows.</p>'''
extra=page('Visual Guidelines / Color',a,'09')+page('Style Guide / Type & Layout',b,'10')+page('Style Guide / Components',c,'11')
screens=[('01-dashboard','Business overview','A shared starting point combines recruitment figures with operational queues, deadlines, and blockers.','Hierarchy: summary metrics → attention queues → trend analysis.'),('02-lead-management','Lead management','Filters and ownership information help staff locate enquiries and coordinate assignments.','Pattern: searchable table with contextual record actions.'),('03-follow-up-planner','Follow-up planner','Scheduled activity gives counselling teams a view of pending and completed follow-ups.','Intent: make the next contact visible alongside student context.'),('04-application-pipeline','Application pipeline','Application stages, intake information, and ownership support admissions tracking.','Pattern: dense records organized through filters and status labels.'),('05-student-application-detail','Student application detail','A dedicated record brings application information and operational activities together.','Intent: reduce repeated searching across disconnected views.'),('06-guided-application','Guided application','A staged form separates student details and supporting information into manageable sections.','Pattern: step navigation and progress feedback; submission persistence remains incomplete.'),('07-institution-directory','Institution directory','Institution information supports destination exploration and student counselling.','Pattern: browse and filter a shared reference catalogue.'),('08-course-catalogue','Course catalogue','Course records support comparison of academic options during counselling.','Intent: provide consistent reference information across student conversations.'),('09-whatsapp-workspace','WhatsApp workspace','Conversation list, chat, and contact context share one communication workspace.','Pattern: three-pane desktop layout; current send behavior is simulated.'),('10-counsellor-performance','Counsellor performance','Comparative reporting helps managers examine activity and conversion indicators.','Intent: provide visibility; displayed figures are prototype data, not measured impact.'),('11-finance-overview','Finance overview','Financial summaries organize commission-related activity and outstanding amounts.','Pattern: summary indicators with supporting operational records.'),('12-agent-management','Agent management','Partner records organize the agent network and referral relationships.','Intent: support partner coordination alongside the admissions lifecycle.')]
for n,(file,title,desc,detail) in enumerate(screens,1):
 uri=(root/'public/final-ui-screens'/f'{file}.jpg').as_uri()
 extra+=f'<section class="screen-page"><div class="eyebrow">THE FINAL EXPERIENCE / {n:02d} OF 12</div><h2>{title}</h2><p class="screen-desc">{desc} {detail}</p><div class="screen-frame"><img src="{uri}"></div><footer>BHE CRM / EXISTING UI EXPORT · SAMPLE DATA · NOT A LIVE CAPTURE <span>{n:02d}</span></footer></section>'
s=s.replace('</body>',extra+'</body>')
Path('tmp/pdf-review/crm-case-study-visual.html').write_text(s)
